    correction: [{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 9</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = -2</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) - 9</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-2) - 9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -11</span>"}],
