    correction: [{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">-(x - y + 1) = -x + y - 1</span>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [-x + y - 1 + x - 1] = -y + 1 + 1</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [1 + y - x + 4] = -1 - y + x - 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -1 - y + 1 + 1 - 1 - y + x - 4 + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = x + (-y - y) + (-1 + 1 + 1 - 1 - 4 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 + 1 + 1 - 1 - 4 + 1 = -3</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - 2y - 3</span>"}],
