    correction: [{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">- (1 - a) = -1 + a</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [-6 - 1 + a - b] = 6 + 1 - a + b</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (b - 2) = -b + 2</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = -b + 6 + 1 - a + b - b + 2</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = -a + (-b + b - b) + (6 + 1 + 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">6 + 1 + 2 = 9</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = -a - b + 9</span>"}],
